	dates := []string{"2015-01-01", "2015-12-31", "1999-03-07"}
	descs := []string{"", "Buy present", "a", "Freude schoner Gotterfunken", "x"}
	changes := []int{0, 1, -1, 1000, -1000, 12345, -12345, 123456, -123456, 1000000, -987654321, 42}
	for _, cur := range currencies {
